cat /app/resources/treasury_bulletin_1941_03.json | python3 -c "
import json
import re
import sys

data = json.load(sys.stdin)

# Get element 275 which is the Values table
for i, elem in enumerate(data['document']['elements']):
    if i == 275:
        content = str(elem.get('content', ''))
        # Find Tobacco and Wool rows
        if 'Tobacco and manufactures' in content:
            lines = content.split('<tr>')
            for line in lines:
                if 'Tobacco and manufactures' in line:
                    print('TOBACCO:', line[:600])
                    print('---')
                if 'Wool and manufactures' in line:
                    print('WOOL:', line[:600])
                    print('---')
"
